-- TomoModForever 1.2.4 release notes.

TomoMod_RegisterLocale("enUS", {
    ["wn_124_quests"] = "New - Dungeon codex: a Quests tab lists the quests of each dungeon for your faction (402 quests over the 35 dungeons and wings), with their level, quest giver and state read from the game: done, in your quest log, or still to take.",
    ["wn_124_triage"] = "New - Bags: what to throw away, what to loot. When your bags are nearly full, the items cheapest to sell carry a number in TomoMod's bags (1 = first to go). With full bags, a gold coin marks the loot worth more than the item it would replace, and tooltips say which item to drop. The bag space banner counts the items that can go. Pinned items, quest items and items your quest log asks for are never suggested.",
})

TomoMod_RegisterLocale("frFR", {
    ["wn_124_quests"] = "Nouveau - Codex des donjons : un onglet Quêtes liste les quêtes de chaque donjon pour ta faction (402 quêtes sur les 35 donjons et ailes), avec leur niveau, leur donneur et leur état lu dans le jeu : faite, dans ton journal, ou à prendre.",
    ["wn_124_triage"] = "Nouveau - Sacs : quoi jeter, quoi ramasser. Quand tes sacs sont presque pleins, les objets les moins chers à la revente portent un numéro dans les sacs TomoMod (1 = le premier à jeter). Sacs pleins, une pièce d'or marque le butin qui vaut plus que l'objet qu'il remplacerait, et les infobulles disent quel objet jeter. L'alerte de place compte les objets à jeter. Les objets épinglés, les objets de quête et ceux que ton journal de quêtes demande ne sont jamais proposés.",
})

TomoMod_RegisterLocale("deDE", {
    ["wn_124_quests"] = "Neu - Dungeon-Kodex: Ein Reiter Quests listet die Quests jedes Dungeons für deine Fraktion (402 Quests in den 35 Dungeons und Flügeln), mit Stufe, Questgeber und dem Zustand aus dem Spiel: erledigt, in deinem Questlog oder noch anzunehmen.",
    ["wn_124_triage"] = "Neu - Taschen: was wegwerfen, was plündern. Wenn deine Taschen fast voll sind, tragen die beim Händler billigsten Gegenstände eine Nummer in den TomoMod-Taschen (1 = zuerst weg). Bei vollen Taschen markiert eine Goldmünze die Beute, die mehr wert ist als der Gegenstand, den sie ersetzen würde, und Tooltips sagen, was du wegwerfen sollst. Das Taschenplatz-Banner zählt die wegwerfbaren Gegenstände. Angeheftete Gegenstände, Questgegenstände und was dein Questlog verlangt, werden nie vorgeschlagen.",
