TomoMod_RegisterLocale("esES", {
    ["wn_124_quests"] = "Nuevo - Códice de mazmorras: una pestaña Misiones muestra las misiones de cada mazmorra para tu facción (402 misiones en las 35 mazmorras y alas), con su nivel, quién la da y su estado según el juego: hecha, en tu registro o por aceptar.",
    ["wn_124_triage"] = "Nuevo - Bolsas: qué tirar, qué despojar. Cuando tus bolsas están casi llenas, los objetos más baratos de vender llevan un número en las bolsas de TomoMod (1 = el primero en irse). Con las bolsas llenas, una moneda de oro marca el botín que vale más que el objeto que reemplazaría, y las descripciones dicen qué objeto tirar. El aviso de espacio cuenta los objetos que se pueden tirar. Los objetos fijados, los de misión y los que pide tu registro de misiones nunca se proponen.",
})

TomoMod_RegisterLocale("itIT", {
    ["wn_124_quests"] = "Nuovo - Codice delle spedizioni: una scheda Missioni elenca le missioni di ogni spedizione per la tua fazione (402 missioni nelle 35 spedizioni e ali), con livello, chi la assegna e lo stato letto dal gioco: completata, nel registro o da prendere.",
    ["wn_124_triage"] = "Nuovo - Borse: cosa buttare, cosa raccogliere. Quando le borse sono quasi piene, gli oggetti più economici da vendere portano un numero nelle borse di TomoMod (1 = il primo da buttare). A borse piene, una moneta d'oro segna il bottino che vale più dell'oggetto che sostituirebbe, e i tooltip dicono quale oggetto buttare. L'avviso di spazio conta gli oggetti da buttare. Gli oggetti fissati, quelli di missione e quelli richiesti dal registro delle missioni non vengono mai proposti.",
})

TomoMod_RegisterLocale("ptBR", {
